#!/usr/bin/env python3
import json
import sys

def migrate_config(path):
    with open(path, 'r') as f:
        data = json.load(f)
    if 'timeout_ms' in data:
        data['timeout_seconds'] = data['timeout_ms'] // 1000
    if 'debug' in data:
        data['log_level'] = 'debug' if data['debug'] else 'info'
    return data

def main():
    if len(sys.argv) < 2:
        print('Usage: migrate.py <path>', file=sys.stderr)
        sys.exit(1)
    path = sys.argv[1]
    try:
        migrated = migrate_config(path)
        print(json.dumps(migrated, indent=2))
    except Exception as e:
        print(f'Error: {e}', file=sys.stderr)
        sys.exit(1)

if __name__ == '__main__':
    main()

